mapper.select:
SELECT 
FROM pipeline_template_version
WHERE deleted = 0
  AND pipeline_template_code = #{pipelineTemplateCode}
  AND version = #{version}
LIMIT 1

mapper.update:
UPDATE pipeline_template_version
SET status = #{status}
WHERE deleted = 0
  AND pipeline_template_code = #{pipelineTemplateCode}
  AND version = #{version}

UPDATE pipeline_template_version
SET status = 'EXPIRED'
WHERE deleted = 0
  AND pipeline_template_code = #{pipelineTemplateCode}
  AND version <> #{excludeVersion}
  AND status <> 'EXPIRED'
